"""Joins the three data-quality checks for the 89 clean HCC cases into one table: DICOM source check (scripts/dq_source_check.py), model-free label-offset screen (scripts/dq_label_offset.py) and the STORED VISTA-3D liver Dice (hackathon evaluation, annotated slices).
Flags: SEG-vs-CT in-plane position offset > 1 mm; edge-screen shift > 10 mm on x or y with gain > 25%; stored VISTA liver Dice < 0.80. (Stored VISTA liver MASKS were never saved, so centroid offset / bbox IoU of the VISTA liver cannot be computed from stored data.)
Usage: python scripts/dq_screen_report.py <dir with the csv/json inputs> (writes SCREEN.md and screen_table.csv there)"""
import csv
import json
import sys

d = sys.argv[1]; c89 = [l.strip() for l in open(f"{d}/clean89_cases.txt")]; src = json.load(open(f"{d}/source_check_clean89.json")); off = {r["case"]: r for r in csv.DictReader(open(f"{d}/label_offset_clean89.csv"))}
liv_tab = {m: {r["case"]: float(r["dice"]) for r in csv.DictReader(open(f"{d}/{f}")) if r["target"] == "liver"} for m, f in (("uid", "stored_vista_eval_uid_route.csv"), ("sop_series+position", "stored_vista_eval_resolved.csv"))}
liv = {c: liv_tab[src[c]["label_method"]][c] for c in c89}      # the stored evaluation that matches each case's conversion (resolved cases: the re-converted evaluation)
rows = []
for c in c89:
    s, o = src[c], off[c]
    rows.append({"case": c, "label_method": s["label_method"], "seg_ct_offset_x_mm": s["delta_ipp_along_column_index_dir_x_mm"]["median"], "seg_ct_offset_y_mm": s["delta_ipp_along_row_index_dir_y_mm"]["median"], "seg_ct_offset_through_plane_max_mm": s["delta_ipp_through_plane_mm"]["max_abs"],
                 "series_ref_ok": s["series_ref_equals_ct_used"], "frame_of_reference_equal": s["frame_of_reference_equal"], "edge_shift_x_mm": o["shift_x_mm"], "edge_shift_y_mm": o["shift_y_mm"], "edge_gain": o["gain_over_zero"], "stored_vista_liver_dice": liv[c],
                 "flag_source": s["flag_inplane_shift_gt_1mm"], "flag_edge": o["flag"] == "True", "flag_vista_dice": liv[c] < 0.80})
with open(f"{d}/screen_table.csv", "w", newline="") as f:
    w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
fl = [r for r in rows if r["flag_source"] or r["flag_edge"] or r["flag_vista_dice"]]
L = ["# Cohort screen of the 89 clean HCC cases (generated by scripts/dq_screen_report.py)", "", f"Flagged by at least one check: {len(fl)} of {len(rows)}.", "", "| case | SEG-CT offset x / y (mm) | edge-screen shift x / y (mm), gain | stored VISTA liver Dice | flags (source / edge / Dice<0.80) |", "|---|---|---|---|---|"]
for r in fl:
    L.append(f"| {r['case']} | {r['seg_ct_offset_x_mm']} / {r['seg_ct_offset_y_mm']} | {r['edge_shift_x_mm']} / {r['edge_shift_y_mm']}, {r['edge_gain']} | {r['stored_vista_liver_dice']:.3f} | {r['flag_source']} / {r['flag_edge']} / {r['flag_vista_dice']} |")
L += ["", f"Source check, all 89: series reference equals the CT series used in {sum(r['series_ref_ok'] for r in rows)}; in-plane SEG-CT position offset > 1 mm in {sum(r['flag_source'] for r in rows)} (HCC_019_773068 only); through-plane offset at most {max(r['seg_ct_offset_through_plane_max_mm'] for r in rows)} mm; FrameOfReferenceUID differs in {sum(not r['frame_of_reference_equal'] for r in rows)} ({', '.join(r['case'] for r in rows if not r['frame_of_reference_equal'])}, positions identical)."]
open(f"{d}/SCREEN.md", "w").write("\n".join(L) + "\n"); print("\n".join(L))
